//! `grpc_dc::Message` adapters for the generated echo messages.
//!
//! The message types themselves are generated by
//! protoc-gen-grpc-dc-rust into `rust/gen/echo_pb.rs` and are
//! dependency-free (inherent `encode`/`decode`, with `decode`
//! reporting `String` errors). The generated stub needs
//! `grpc_dc::Message`; these two impls are the whole bridge, so
//! the examples and the Wasm facade share one generated message
//! implementation instead of a hand-written one.

impl grpc_dc::Message for crate::pb::EchoRequest {
    fn encode(&self) -> Vec<u8> {
        crate::pb::EchoRequest::encode(self)
    }

    fn decode(bytes: &[u8]) -> Result<Self, grpc_dc::Status> {
        crate::pb::EchoRequest::decode(bytes).map_err(grpc_dc::Status::invalid_argument)
    }
}

impl grpc_dc::Message for crate::pb::EchoResponse {
    fn encode(&self) -> Vec<u8> {
        crate::pb::EchoResponse::encode(self)
    }

    fn decode(bytes: &[u8]) -> Result<Self, grpc_dc::Status> {
        crate::pb::EchoResponse::decode(bytes).map_err(grpc_dc::Status::invalid_argument)
    }
}
